import sys
try:
    import pysat
    print("pysat is available")
except ImportError:
    print("pysat is NOT available")

from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import time

def solve_graceful():
    V = 18
    E = 33

    edges = []
    # Cliques
    for g in range(6):
        for i in range(3):
            for j in range(i+1, 3):
                edges.append((g*3 + i, g*3 + j))

    # Connections
    for g in range(5):
        for i in range(3):
            edges.append((g*3 + i, (g+1)*3 + i))

    solver = Glucose4()

    def var_x(v, l):
        return v * (E + 1) + l + 1

    def var_y(e, d):
        return V * (E + 1) + e * E + d

    # 1. Each vertex has exactly one label
    for v in range(V):
        solver.add_clause([var_x(v, l) for l in range(E + 1)])
        for l1 in range(E + 1):
            for l2 in range(l1 + 1, E + 1):
                solver.add_clause([-var_x(v, l1), -var_x(v, l2)])

    # 2. Each label is assigned to at most one vertex
    for l in range(E + 1):
        for v1 in range(V):
            for v2 in range(v1 + 1, V):
                solver.add_clause([-var_x(v1, l), -var_x(v2, l)])

    # 3. Each edge has exactly one difference
    for e in range(E):
        solver.add_clause([var_y(e, d) for d in range(1, E + 1)])
        for d1 in range(1, E + 1):
            for d2 in range(d1 + 1, E + 1):
                solver.add_clause([-var_y(e, d1), -var_y(e, d2)])

    # 4. Each difference is assigned to exactly one edge
    for d in range(1, E + 1):
        solver.add_clause([var_y(e, d) for e in range(E)])
        for e1 in range(E):
            for e2 in range(e1 + 1, E):
                solver.add_clause([-var_y(e1, d), -var_y(e2, d)])

    # 5. Edge difference relation
    for e_idx, (u, v) in enumerate(edges):
        for d in range(1, E + 1):
            # If y_{e, d} is true, then one of the pairs must be true
            # y_{e, d} => OR_l (x_{u, l} AND x_{v, l+d}) OR (x_{u, l+d} AND x_{v, l})
            # This is a bit large to encode directly as CNF.
            # Let's introduce auxiliary variables for the pairs.
            pass

    # Actually, we can just say:
    # x_{u, l1} AND x_{v, l2} => y_{e, |l1 - l2|}
    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(E + 1):
            for l2 in range(E + 1):
                if l1 != l2:
                    d = abs(l1 - l2)
                    solver.add_clause([-var_x(u, l1), -var_x(v, l2), var_y(e_idx, d)])

    # Symmetry breaking
    # The graph has symmetries.
    # 1. Reversing the cliques: clique 0 <-> clique 5, etc.
    # 2. Permuting vertices within a clique? No, the connections between cliques are parallel.
    # Wait, the connections are (g*3+i, (g+1)*3+i). So we can permute the 3 "tracks" across all cliques simultaneously!
    # Track 0: 0, 3, 6, 9, 12, 15
    # Track 1: 1, 4, 7, 10, 13, 16
    # Track 2: 2, 5, 8, 11, 14, 17
    # We can enforce that label(0) < label(1) < label(2).
    solver.add_clause([-var_x(0, l1) for l1 in range(E+1)] + [var_x(1, l2) for l2 in range(E+1)]) # Not valid CNF

    # Let's just add simple symmetry breaking:
    # label(0) < label(1) < label(2)
    for l1 in range(E + 1):
        for l2 in range(l1 + 1):
            solver.add_clause([-var_x(0, l1), -var_x(1, l2)])
            solver.add_clause([-var_x(1, l1), -var_x(2, l2)])

    # Reverse symmetry: label(0) < label(15) (Wait, track 0, clique 0 vs track 0, clique 5)
    # Actually, reversing the cliques means mapping clique g to 5-g.
    # But does it preserve the graph? Yes, clique g is connected to g+1.
    # So we can enforce label(0) < label(15) or something.
    # Let's just enforce label(0) < label(15)
    for l1 in range(E + 1):
        for l2 in range(l1 + 1):
            solver.add_clause([-var_x(0, l1), -var_x(15, l2)])

    # Also, graceful labeling has a complement symmetry: L -> E - L.
    # We can enforce that label(0) < E / 2.
    for l in range(E // 2 + 1, E + 1):
        solver.add_clause([-var_x(0, l)])

    print("Solving...")
    start = time.time()
    res = solver.solve()
    print("Solved in", time.time() - start)

    if res:
        model = solver.get_model()
        labels = [-1] * V
        for v in range(V):
            for l in range(E + 1):
                if var_x(v, l) in model:
                    labels[v] = l
        return labels
    else:
        return None

print(solve_graceful())
